#!/usr/bin/env node
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    —
 * depends    —
 * used by    —
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
/**
 * Build v29 lab level curves (242-252) from validated references.
 *
 *   node scripts/build-lab-v29-curves.mjs
 *   node scripts/build-lab-v29-curves.mjs --write-catalog
 *
 * Sources:
 * - Enemy labs 242-245: LAB_CATALOG (EP-validated)
 * - Fleet 246-248: same curve × (baseCoin 1e21/1e18, baseTime 1440000/1260000)
 * - Recharge Bastion 250: recharge_demon_mode (same Initialize base 5.5e11 / 450000s)
 * - Bastion/Cells mastery 249/251: standard card-mastery ladder (masteries.ts / catalog)
 * - Global Presets 252: card_presets one-shot (Initialize NO_STORE; tier 11 gate only)
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'

const SDK_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const REPO_ROOT = path.resolve(SDK_ROOT, '..', '..')
const OUT = path.join(REPO_ROOT, 'temp', 'v29-lab-curves-built.json')
const CATALOG_PATH = path.join(SDK_ROOT, 'src', 'data', 'labs', 'catalog.ts')
const WRITE = process.argv.includes('--write-catalog')

const { LAB_CATALOG } = await import(pathToFileURL(path.join(SDK_ROOT, 'src/data/labs/catalog.ts')).href)

const bySlug = Object.fromEntries(LAB_CATALOG.map(row => [row.slug, row]))

function scaleEnemyCurve(refSlug, baseCoin, baseTime, levelMax) {
  const ref = bySlug[refSlug]
  if (!ref?.levels?.length) throw new Error(`missing reference ${refSlug}`)
  const refL1 = ref.levels.find(r => r.level === 1)
  if (!refL1) throw new Error(`no L1 on ${refSlug}`)
  const coinScale = baseCoin / refL1.cost
  const timeScale = baseTime / (parseDurationSeconds(refL1.duration) ?? baseTime)
  return ref.levels
    .filter(r => r.level <= levelMax)
    .map(r => ({
      level: r.level,
      duration: formatDuration(parseDurationSeconds(r.duration) * timeScale),
      cost: Math.round(r.cost * coinScale),
    }))
}

function parseDurationSeconds(raw) {
  const s = String(raw).trim()
  if (!s || s === '0s') return 0
  const clock = s.split(':')
  if (clock.length === 3 && !s.includes('d')) {
    return Number(clock[0]) * 3600 + Number(clock[1]) * 60 + Number(clock[2])
  }
  const spans = s.match(/(\d+(?:\.\d+)?)\s*([dhms])/gi)
  if (!spans) return null
  const UNIT = { d: 86400, h: 3600, m: 60, s: 1 }
  let total = 0
  for (const span of spans) {
    const amount = Number.parseFloat(span)
    const unit = span.trim().slice(-1).toLowerCase()
    total += amount * UNIT[unit]
  }
  return Math.round(total)
}

function formatDuration(seconds) {
  const s = Math.round(seconds)
  if (s <= 0) return '0s'
  const h = Math.floor(s / 3600)
  const m = Math.floor((s % 3600) / 60)
  const sec = s % 60
  if (h >= 24) {
    const d = Math.floor(h / 24)
    const hr = h % 24
    return `${d}d ${hr}h ${m}m`
  }
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:${String(sec).padStart(2, '0')}`
}

function copyLevels(slug) {
  const row = bySlug[slug]
  if (!row?.levels) throw new Error(`missing ${slug}`)
  return row.levels.map(l => ({ ...l }))
}

const BUILT = {
  overcharge_exponent_reducer: {
    index: 246,
    name: 'Overcharge Exponent Reducer',
    category: 'Fleet',
    slug: 'overcharge_exponent_reducer',
    base: 0,
    value: 0,
    source: 'enemy curve × Initialize base 1e21 / 1440000s',
    levels: scaleEnemyCurve('overcharge_enemy_health', 1e21, 1440000, 30),
  },
  commander_radius: {
    index: 247,
    name: 'Commander Radius',
    category: 'Fleet',
    slug: 'commander_radius',
    base: 0,
    value: 0,
    source: 'enemy curve × Initialize base 1e21 / 1440000s',
    levels: scaleEnemyCurve('overcharge_enemy_health', 1e21, 1440000, 30),
  },
  saboteur_attack_speed: {
    index: 248,
    name: 'Saboteur Attack Speed',
    category: 'Fleet',
    slug: 'saboteur_attack_speed',
    base: 0,
    value: 0,
    source: 'enemy curve × Initialize base 1e21 / 1440000s',
    levels: scaleEnemyCurve('overcharge_enemy_health', 1e21, 1440000, 30),
  },
  recharge_bastion: {
    index: 250,
    name: 'Recharge Bastion',
    category: 'Cards',
    slug: 'recharge_bastion',
    base: 0,
    value: 0,
    source: 'recharge_demon_mode curve (Initialize base 5.5e11 / 450000s)',
    levels: copyLevels('recharge_demon_mode'),
  },
  global_presets: {
    index: 252,
    name: 'Global Presets',
    category: 'Main',
    slug: 'global_presets',
    base: 0,
    value: 1,
    source: 'card_presets one-shot (Initialize NO_STORE coin/time; tier 11 mile 5 gate)',
    levels: copyLevels('card_presets'),
  },
}

fs.mkdirSync(path.dirname(OUT), { recursive: true })
fs.writeFileSync(
  OUT,
  JSON.stringify(
    {
      builtAt: new Date().toISOString(),
      provenance:
        'Scaled from EP-validated enemy curve + recharge/mastery/preset templates; fleet bases from Lab.Initialize HARD',
      labs: BUILT,
    },
    null,
    2,
  ) + '\n',
  'utf8',
)
console.log(`wrote ${path.relative(REPO_ROOT, OUT)}`)
for (const [slug, row] of Object.entries(BUILT)) {
  console.log(`  ${slug}: ${row.levels.length} levels, L1=${row.levels.find(l => l.level === 1)?.cost}`)
}

if (!WRITE) {
  console.log('\ndry run — pass --write-catalog to patch catalog.ts')
  process.exit(0)
}

let src = fs.readFileSync(CATALOG_PATH, 'utf8')
for (const row of Object.values(BUILT)) {
  if (src.includes(`slug: "${row.slug}"`)) {
    console.log(`skip existing ${row.slug}`)
    continue
  }
  const { source, ...catalogRow } = row
  delete catalogRow.index
  const block =
    '\n{\n'
    + `    slug: ${JSON.stringify(catalogRow.slug)},\n`
    + `    name: ${JSON.stringify(catalogRow.name)},\n`
    + `    category: ${JSON.stringify(catalogRow.category)},\n`
    + (catalogRow.description ? `    description: ${JSON.stringify(catalogRow.description)},\n` : '')
    + (catalogRow.unit ? `    unit: ${JSON.stringify(catalogRow.unit)},\n` : '')
    + `    base: ${catalogRow.base},\n`
    + (catalogRow.value !== undefined && typeof catalogRow.value === 'object'
      ? `    value: ${JSON.stringify(catalogRow.value, null, 6).replace(/\n/g, '\n    ')},\n`
      : `    value: ${catalogRow.value},\n`)
    + `    // v29 curve: ${source}\n`
    + `    levels: ${JSON.stringify(catalogRow.levels, null, 6).replace(/\n/g, '\n    ')},\n`
    + '  },'

  const anchor = 'slug: "package_after_boss"'
  if (!src.includes(anchor)) throw new Error('catalog anchor missing')
  src = src.replace(`{\n    slug: "package_after_boss"`, block + '\n{\n    slug: "package_after_boss"')
  console.log(`inserted ${row.slug}`)
}

fs.writeFileSync(CATALOG_PATH, src, 'utf8')
console.log(`updated ${path.relative(REPO_ROOT, CATALOG_PATH)}`)
